package com.qiban.companion;
import ai.onnxruntime.*;
import java.io.*;
import java.nio.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import org.json.*;

/** Same G2P, WordPiece alignment and staged GPT-SoVITS tensors as the iOS engine. */
final class NeuralVoice {
    private final OrtEnvironment env=OrtEnvironment.getEnvironment();
    private final File root,model;private final String language;private final JSONObject condition;
    private final float[] reference;private final long[] prompt;private final float[] spectrogram;private final JSONObject vocabulary;
    private final boolean accelerated;private final int threads;
    private final Random random=new java.security.SecureRandom();
    NeuralVoice(File root,String language,boolean accelerated,int threads)throws Exception {
        this.root=root;this.language=language;this.accelerated=accelerated;this.threads=threads;model=new File(root,"voices/"+language);condition=FilesSupport.json(new File(model,"conditioning.json"),128*1024);
        long[] phones=longs(condition.getJSONArray("referencePhones"));long[] specShape=longs(condition.getJSONArray("spectrogramShape"));long[] pShape=longs(condition.getJSONArray("promptShape"));
        if(phones.length<1||phones.length>500||specShape.length!=3||specShape[0]!=1||specShape[1]!=1025||specShape[2]<1||specShape[2]>1500||pShape.length!=2||pShape[0]!=1||pShape[1]<1||pShape[1]>500||condition.getInt("sampleRate")!=32000||condition.getInt("cacheLimit")!=768)throw new IOException("语音参考特征不兼容。");
        reference=floats(new File(model,"reference_bert.bin"),phones.length*1024);prompt=readLongs(new File(model,"prompt_semantic.bin"),(int)pShape[1]);spectrogram=floats(new File(model,"refer_spec.bin"),(int)(1025*specShape[2]));
        if(!NativeG2P.initialize(new File(root,"resources").getAbsolutePath().getBytes(StandardCharsets.UTF_8),new File(model,"config.json").getAbsolutePath().getBytes(StandardCharsets.UTF_8)))throw new IOException("中日语音字典未就绪，请重新导入完整包。");
        vocabulary=language.equals("zh")?FilesSupport.json(new File(root,"shared/tokenizer.json"),4*1024*1024).getJSONObject("model").getJSONObject("vocab"):null;
    }
    private record Tensor(float[] floats,long[] longs,long[] shape){}
    private interface Stage<T>{T run(OrtSession s)throws Exception;}
    private <T>T stage(String name,AtomicBoolean cancelled,Stage<T> run)throws Exception {check(cancelled);File file=name.equals("bert")?new File(root,"shared/bert.onnx"):new File(model,name.equals("encoder")?"gpt_encoder.onnx":name.equals("step")?"gpt_step.onnx":"sovits.onnx");try(OrtSession.SessionOptions options=options(name,accelerated);OrtSession session=env.createSession(file.getPath(),options)){return run.run(session);}catch(OrtException e){if(!accelerated||!List.of("bert","sovits").contains(name))throw e;check(cancelled);try(OrtSession.SessionOptions options=options(name,false);OrtSession session=env.createSession(file.getPath(),options)){return run.run(session);}}}
    private OrtSession.SessionOptions options(String stage,boolean nnapi)throws OrtException {OrtSession.SessionOptions options=new OrtSession.SessionOptions();options.setIntraOpNumThreads(threads);options.setInterOpNumThreads(1);options.setMemoryPatternOptimization(false);options.setOptimizationLevel(OrtSession.SessionOptions.OptLevel.ALL_OPT);if(nnapi&&List.of("bert","sovits").contains(stage)){try{options.addNnapi(java.util.EnumSet.of(ai.onnxruntime.providers.NNAPIFlags.CPU_DISABLED));}catch(OrtException ignored){}}return options;}
    private static void check(AtomicBoolean c)throws InterruptedException{if(c.get()||Thread.currentThread().isInterrupted())throw new InterruptedException("朗读已停止。");}
    private OnnxTensor tensor(Tensor value)throws OrtException{return value.floats!=null?OnnxTensor.createTensor(env,FloatBuffer.wrap(value.floats),value.shape):OnnxTensor.createTensor(env,LongBuffer.wrap(value.longs),value.shape);}
    private Map<String,Tensor> run(OrtSession session,Map<String,Tensor> in,Set<String> output)throws Exception {Map<String,OnnxTensor> values=new LinkedHashMap<>();try{for(var e:in.entrySet())values.put(e.getKey(),tensor(e.getValue()));try(OrtSession.Result result=session.run(values,output)){Map<String,Tensor> out=new HashMap<>();for(String key:output){OnnxTensor v=(OnnxTensor)result.get(key).orElseThrow(()->new IOException("模型输出缺失："+key));TensorInfo info=v.getInfo();if(info.type==OnnxJavaType.FLOAT){FloatBuffer b=v.getFloatBuffer();float[] f=new float[b.remaining()];b.get(f);out.put(key,new Tensor(f,null,info.getShape()));}else if(info.type==OnnxJavaType.INT64){LongBuffer b=v.getLongBuffer();long[] l=new long[b.remaining()];b.get(l);out.put(key,new Tensor(null,l,info.getShape()));}else throw new IOException("模型输出类型不兼容。");}return out;}}finally{for(OnnxTensor v:values.values())v.close();}}
    private static Tensor f(float[] values,long...shape){return new Tensor(values,null,shape);}private static Tensor l(long[] values,long...shape){return new Tensor(null,values,shape);}
    private Tensor copiedOutput(OrtSession.Result result,String name)throws Exception {OnnxTensor tensor=(OnnxTensor)result.get(name).orElseThrow(()->new IOException("模型输出缺失："+name));TensorInfo info=tensor.getInfo();if(info.type==OnnxJavaType.FLOAT){FloatBuffer buffer=tensor.getFloatBuffer();float[] values=new float[buffer.remaining()];buffer.get(values);return f(values,info.getShape());}LongBuffer buffer=tensor.getLongBuffer();long[] values=new long[buffer.remaining()];buffer.get(values);return l(values,info.getShape());}
    private long[] decode(OrtSession session,Map<String,Tensor> seed,Tensor x,Tensor y,long first,int max,AtomicBoolean cancelled)throws Exception {
        // Keep each decoder output alive as the next step's cache. No per-token
        // Java heap copies of K/V, and the encoder's owned snapshots are released.
        try(OnnxTensor xValue=tensor(x);OnnxTensor yValue=tensor(y);OnnxTensor initialK=tensor(seed.remove("k_cache"));OnnxTensor initialV=tensor(seed.remove("v_cache"))){
            seed.clear();OnnxTensor k=initialK,v=initialV;OrtSession.Result previous=null;List<Long> tokens=new ArrayList<>();long current=first;
            try{for(int index=0;index<max;index++){check(cancelled);if(current==1024)break;tokens.add(current);
                try(OnnxTensor sample=tensor(l(new long[]{current},1,1));OnnxTensor idx=tensor(l(new long[]{index},1))){
                    OrtSession.Result next=session.run(Map.of("samples",sample,"k_cache",k,"v_cache",v,"idx",idx,"x_len",xValue,"y_len",yValue),Set.of("topk_values","topk_indices","k_cache_new","v_cache_new"));
                    try{long chosen=sample(Map.of("topk_values",copiedOutput(next,"topk_values"),"topk_indices",copiedOutput(next,"topk_indices")),tokens,tokens.size()>=5);OnnxTensor nextK=(OnnxTensor)next.get("k_cache_new").orElseThrow(()->new IOException("语义缓存输出缺失")),nextV=(OnnxTensor)next.get("v_cache_new").orElseThrow(()->new IOException("语义缓存输出缺失"));if(previous!=null)previous.close();previous=next;next=null;k=nextK;v=nextV;current=chosen;}finally{if(next!=null)next.close();}
                }
            }if(current!=1024||tokens.size()<5)throw new IOException("本句语音未正常结束，请缩短后重试。");return tokens.stream().mapToLong(z->z).toArray();}finally{if(previous!=null)previous.close();}
        }
    }
    private static long[] longs(JSONArray values)throws Exception{long[] out=new long[values.length()];for(int i=0;i<out.length;i++)out[i]=values.getLong(i);return out;}
    private static float[] floats(File file,int count)throws Exception{if(file.length()!=count*4L||count<1||count>16*1024*1024)throw new IOException("语音浮点特征长度无效。");ByteBuffer b=ByteBuffer.wrap(java.nio.file.Files.readAllBytes(file.toPath())).order(ByteOrder.LITTLE_ENDIAN);float[] out=new float[count];b.asFloatBuffer().get(out);return out;}
    private static long[] readLongs(File file,int count)throws Exception{if(file.length()!=count*8L)throw new IOException("语音整数特征长度无效。");LongBuffer b=ByteBuffer.wrap(java.nio.file.Files.readAllBytes(file.toPath())).order(ByteOrder.LITTLE_ENDIAN).asLongBuffer();long[] out=new long[count];b.get(out);return out;}
    private record Encoding(long[] ids,int[] mapping){}
    private Encoding encode(String text)throws Exception {int[] chars=text.codePoints().toArray(),mapping=new int[chars.length];ArrayList<Long> ids=new ArrayList<>();ids.add(vocabulary.getLong("[CLS]"));int index=0;while(index<chars.length){if(Character.isWhitespace(chars[index])){index++;continue;}int end=index+1;if(ascii(chars[index]))while(end<chars.length&&ascii(chars[end]))end++;String word=new String(chars,index,end-index).toLowerCase(Locale.ROOT);ArrayList<long[]> parts=new ArrayList<>();int start=0;while(start<word.length()){int stop=word.length();long[] found=null;while(stop>start){String token=(start>0?"##":"")+word.substring(start,stop);if(vocabulary.has(token)){found=new long[]{vocabulary.getLong(token),start,stop};break;}stop--;}if(found==null){parts.clear();parts.add(new long[]{vocabulary.getLong("[UNK]"),0,word.length()});break;}parts.add(found);start=(int)found[2];}for(long[] part:parts){int position=ids.size();ids.add(part[0]);for(int offset=(int)part[1];offset<part[2]&&index+offset<end;offset++)mapping[index+offset]=position;}index=end;}ids.add(vocabulary.getLong("[SEP]"));return new Encoding(ids.stream().mapToLong(x->x).toArray(),mapping);}
    private static boolean ascii(int c){return c>=65&&c<=90||c>=97&&c<=122||c>=48&&c<=57;}
    private long sample(Map<String,Tensor> result,List<Long> history,boolean allowEnd)throws Exception {float[] values=result.get("topk_values").floats;long[] ids=result.get("topk_indices").longs;if(values.length!=ids.length||ids.length<1||ids.length>1025)throw new IOException("语义采样维度无效。");ArrayList<double[]> choices=new ArrayList<>();for(int i=0;i<ids.length;i++){long id=ids[i];float value=values[i];if(id<0||id>1024||id==1024&&!allowEnd||!Float.isFinite(value))continue;if(history.contains(id))value=value<0?value*1.35f:value/1.35f;choices.add(new double[]{id,value/.8});}choices.sort((a,b)->Double.compare(b[1],a[1]));if(choices.isEmpty())throw new IOException("语义采样没有候选。");if(choices.size()>15)choices.subList(15,choices.size()).clear();double sum=0,max=choices.get(0)[1];for(double[] c:choices)sum+=c[1]=Math.exp(c[1]-max);double draw=random.nextDouble()*sum;for(double[] c:choices){draw-=c[1];if(draw<=0)return(long)c[0];}return(long)choices.get(choices.size()-1)[0];}
    float[] synthesize(String text,float speed,AtomicBoolean cancelled)throws Exception {
        check(cancelled);JSONObject parsed=new JSONObject(new String(NativeG2P.process(text.getBytes(StandardCharsets.UTF_8),language.getBytes(StandardCharsets.UTF_8)),StandardCharsets.UTF_8));if(parsed.has("error"))throw new IOException("文字转音素："+parsed.getString("error"));long[] phones=longs(parsed.getJSONArray("ids"));if(phones.length<1||phones.length>400||Arrays.stream(phones).anyMatch(v->v<0||v>=732))throw new IOException("音素结果无效，请缩短台词。");int n=phones.length;float[] targetFeatures=new float[1024*n];
        if(language.equals("zh")){Encoding encoded=encode(parsed.getString("text"));long[] repeats=longs(parsed.getJSONArray("word2ph"));if(encoded.ids.length>512||repeats.length!=encoded.mapping.length||Arrays.stream(repeats).sum()!=n||Arrays.stream(repeats).anyMatch(v->v<0||v>12))throw new IOException("文字与音素无法对齐。");long[] ones=new long[encoded.ids.length];Arrays.fill(ones,1);Tensor hidden=stage("bert",cancelled,s->run(s,Map.of("input_ids",l(encoded.ids,1,encoded.ids.length),"attention_mask",l(ones,1,ones.length),"token_type_ids",l(new long[ones.length],1,ones.length)),Set.of("hidden_states")).get("hidden_states"));if(hidden.floats.length!=ones.length*1024)throw new IOException("文字语义维度不兼容。");int position=0;for(int c=0;c<repeats.length;c++){for(int channel=0;channel<1024;channel++)for(int off=0;off<repeats[c];off++)targetFeatures[channel*n+position+off]=hidden.floats[encoded.mapping[c]*1024+channel];position+=repeats[c];}}
        long[] ref=longs(condition.getJSONArray("referencePhones")),all=Arrays.copyOf(ref,ref.length+n);System.arraycopy(phones,0,all,ref.length,n);float[] features=new float[1024*all.length];for(int channel=0;channel<1024;channel++){System.arraycopy(reference,channel*ref.length,features,channel*all.length,ref.length);System.arraycopy(targetFeatures,channel*n,features,channel*all.length+ref.length,n);}
        Map<String,Tensor> seed=stage("encoder",cancelled,s->run(s,Map.of("phoneme_ids",l(all,1,all.length),"prompts",l(prompt,longs(condition.getJSONArray("promptShape"))),"bert_feature",f(features,1,1024,all.length)),Set.of("topk_values","topk_indices","k_cache","v_cache","x_len","y_len")));
        Tensor x=seed.get("x_len"),y=seed.get("y_len");if(x.longs.length!=1||y.longs.length!=1||x.longs[0]<0||y.longs[0]<0)throw new IOException("语义长度输出无效。");int max=(int)Math.min(375,768-x.longs[0]-y.longs[0]-2);if(max<25)throw new IOException("台词过长，请拆成短句。");long first=sample(seed,List.of(),false);
        long[] semantic=stage("step",cancelled,s->decode(s,seed,x,y,first,max,cancelled));
        seed.clear();float[] samples=stage("sovits",cancelled,s->run(s,Map.of("pred_semantic",l(semantic,1,1,semantic.length),"text_seq",l(phones,1,n),"refer_spec",f(spectrogram,longs(condition.getJSONArray("spectrogramShape"))),"speed",f(new float[]{speed},1)),Set.of("audio")).get("audio").floats);check(cancelled);if(samples.length==0||samples.length>32000*20)throw new IOException("生成音频长度无效。");boolean audible=false;for(float v:samples){if(!Float.isFinite(v))throw new IOException("生成音频含无效数值。");audible|=Math.abs(v)>.0001;}if(!audible)throw new IOException("生成音频为空。");return samples;
    }
}
